<script lang="ts">export let label='';export let value:any='';export let options:string[]=[];export let labels:Record<string,string>={};export let name='';export let error='';</script>
<label data-field-path={name || undefined} class="grid min-w-0 gap-1 text-sm font-semibold text-ink"><span>{label}</span><select {name} class={`h-10 min-w-0 rounded-lg border bg-surface px-3 font-normal outline-none ${error?'border-red-400 focus:border-red-500':'border-ink/15 focus:border-forest'}`} aria-invalid={error?'true':undefined} bind:value><option value="">Select…</option>{#each options as option}<option value={option}>{labels[option]??option.replaceAll('_',' ').replace(/\b\w/g,c=>c.toUpperCase())}</option>{/each}</select>{#if error}<small class="font-medium text-red-600">{error}</small>{/if}</label>
